(() => {
  const DAY_MS = 864e5;
  const MAX_PERIODS = 5;
  function checkFields(input, allowed) {
    if (input === null || typeof input !== "object") {
      throw new Error("input must be an object");
    }
    for (const key of Object.keys(input)) {
      if (!allowed.includes(key)) {
        throw new Error("unknown field: " + key);
      }
    }
  }
  function countLatePeriods(input) {
    checkFields(input, ["deadline", "submittedAt"]);
    const diff = input.submittedAt - input.deadline;
    if (!(diff > 0)) return 0;
    return Math.ceil(diff / DAY_MS);
  }
  function applyLatePenalty(input) {
    checkFields(input, ["maxPoints", "rawScore", "deadline", "submittedAt"]);
    const { maxPoints, rawScore, deadline, submittedAt } = input;
    const periodsLate = countLatePeriods({ deadline, submittedAt });
    let score;
    if (periodsLate > MAX_PERIODS) {
      score = 0;
    } else {
      score = Math.max(0, rawScore - maxPoints * periodsLate / 10);
    }
    const deduction = rawScore - score;
    return { periodsLate, deduction, score };
  }
  return { countLatePeriods, applyLatePenalty };
})()

