build.unitScript:
const H = 36e5;
const D = 17e11;
test("work submitted at or before the deadline keeps its raw score", () => {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: D, submittedAt: D }), { periodsLate: 0, deduction: 0, score: 45 });
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: D, submittedAt: D - H }), { periodsLate: 0, deduction: 0, score: 45 });
  assert.equal(code.countLatePeriods({ deadline: D, submittedAt: D }), 0);
});
test("1 hour late loses 5 of 50 points and 49 hours late loses 15", () => {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: D, submittedAt: D + H }), { periodsLate: 1, deduction: 5, score: 40 });
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: D, submittedAt: D + 49 * H }), { periodsLate: 3, deduction: 15, score: 30 });
});
test("120 hours and 1 minute late is 6 periods and scores 0", () => {
  const r = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: D, submittedAt: D + 120 * H + 6e4 });
  assert.equal(r.periodsLate, 6);
  assert.equal(r.score, 0);
});
test("exactly 24 or 120 hours late does not start the next period", () => {
  assert.equal(code.countLatePeriods({ deadline: D, submittedAt: D + 24 * H }), 1);
  assert.equal(code.countLatePeriods({ deadline: D, submittedAt: D + 24 * H + 1 }), 2);
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: D, submittedAt: D + 120 * H }), { periodsLate: 5, deduction: 25, score: 20 });
});
test("a penalised score never goes below 0", () => {
  const r = code.applyLatePenalty({ maxPoints: 50, rawScore: 10, deadline: D, submittedAt: D + 49 * H });
  assert.equal(r.periodsLate, 3);
  assert.equal(r.score, 0);
});
test("an unknown input field is rejected by both functions", () => {
  assert.throws(() => code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: D, submittedAt: D, extra: 1 }), /unknown field: extra/);
  assert.throws(() => code.countLatePeriods({ deadline: D, submittedAt: D, rawScore: 45 }), /unknown field: rawScore/);
});

build.testScript:
test("submission exactly at the deadline is not penalised", function() {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1e12, submittedAt: 1e12 });
  assert.equal(result.periodsLate, 0);
  assert.equal(result.deduction, 0);
  assert.equal(result.score, 45);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 1e12 }), 0);
});
test("submission one millisecond before the deadline is not penalised", function() {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1e12, submittedAt: 999999999999 });
  assert.equal(result.periodsLate, 0);
  assert.equal(result.deduction, 0);
  assert.equal(result.score, 45);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 999999999999 }), 0);
});
test("one millisecond late starts one period and deducts ten percent of the maximum", function() {
  var result = code.applyLatePenalty({ maxPoints: 80, rawScore: 45, deadline: 1e12, submittedAt: 1000000000001 });
  assert.equal(result.periodsLate, 1);
  assert.equal(result.deduction, 8);
  assert.equal(result.score, 37);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 1000000000001 }), 1);
});
test("one hour late deducts ten percent of the maximum not the raw score", function() {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1e12, submittedAt: 10000036e5 });
  assert.equal(result.periodsLate, 1);
  assert.equal(result.deduction, 5);
  assert.equal(result.score, 40);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 10000036e5 }), 1);
});
test("exactly twenty four hours late does not start a second period", function() {
  var result = code.applyLatePenalty({ maxPoints: 80, rawScore: 45, deadline: 1e12, submittedAt: 10000864e5 });
  assert.equal(result.periodsLate, 1);
  assert.equal(result.deduction, 8);
  assert.equal(result.score, 37);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 10000864e5 }), 1);
});
test("twenty four hours and one millisecond late starts a second period", function() {
  var result = code.applyLatePenalty({ maxPoints: 80, rawScore: 45, deadline: 1e12, submittedAt: 1000086400001 });
  assert.equal(result.periodsLate, 2);
  assert.equal(result.deduction, 16);
  assert.equal(result.score, 29);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 1000086400001 }), 2);
});
test("forty nine hours late counts as three periods", function() {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1e12, submittedAt: 10001764e5 });
  assert.equal(result.periodsLate, 3);
  assert.equal(result.deduction, 15);
  assert.equal(result.score, 30);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 10001764e5 }), 3);
});
test("exactly seventy two hours late does not start a fourth period", function() {
  var result = code.applyLatePenalty({ maxPoints: 80, rawScore: 45, deadline: 1e12, submittedAt: 10002592e5 });
  assert.equal(result.periodsLate, 3);
  assert.equal(result.deduction, 24);
  assert.equal(result.score, 21);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 10002592e5 }), 3);
});
test("seventy two hours and one millisecond late starts a fourth period", function() {
  var result = code.applyLatePenalty({ maxPoints: 80, rawScore: 45, deadline: 1e12, submittedAt: 1000259200001 });
  assert.equal(result.periodsLate, 4);
  assert.equal(result.deduction, 32);
  assert.equal(result.score, 13);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 1000259200001 }), 4);
});
test("exactly one hundred twenty hours late counts as five periods", function() {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1e12, submittedAt: 1000432e6 });
  assert.equal(result.periodsLate, 5);
  assert.equal(result.deduction, 25);
  assert.equal(result.score, 20);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 1000432e6 }), 5);
});
test("one hundred twenty hours and one millisecond late scores zero", function() {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1e12, submittedAt: 1000432000001 });
  assert.equal(result.periodsLate, 6);
  assert.equal(result.score, 0);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 1000432000001 }), 6);
});
test("one hundred twenty hours and one minute late scores zero", function() {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1e12, submittedAt: 100043206e4 });
  assert.equal(result.periodsLate, 6);
  assert.equal(result.score, 0);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 100043206e4 }), 6);
});
test("a penalty that would fall below zero is clamped to zero", function() {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 10, deadline: 1e12, submittedAt: 100018e7 });
  assert.equal(result.periodsLate, 3);
  assert.equal(result.score, 0);
  assert.equal(code.countLatePeriods({ deadline: 1e12, submittedAt: 100018e7 }), 3);
});
test("twenty five hours across the new year counts as two periods not one calendar day", function() {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 314496e5, submittedAt: 315396e5 });
  assert.equal(result.periodsLate, 2);
  assert.equal(result.deduction, 10);
  assert.equal(result.score, 35);
  assert.equal(code.countLatePeriods({ deadline: 314496e5, submittedAt: 315396e5 }), 2);
});
test("twenty five hours across a leap day counts as two periods not one calendar day", function() {
  var result = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 682128e5, submittedAt: 683028e5 });
  assert.equal(result.periodsLate, 2);
  assert.equal(result.deduction, 10);
  assert.equal(result.score, 35);
  assert.equal(code.countLatePeriods({ deadline: 682128e5, submittedAt: 683028e5 }), 2);
});
test("an unknown field throws an error naming that field", function() {
  assert.throws(function() {
    code.applyLatePenalty({
      maxPoints: 50,
      rawScore: 45,
      note: 1,
      deadline: 1e12,
      submittedAt: 1e12
    });
  }, /unknown field: note/);
  assert.throws(function() {
    code.countLatePeriods({
      deadline: 1e12,
      maxPoints: 50,
      submittedAt: 1e12
    });
  }, /unknown field: maxPoints/);
});

